<script setup lang="ts">
import { appPath } from '../../lib/app-path';
import { computed, nextTick, onBeforeUnmount, ref, watch } from "vue";
import { ArrowDown, ArrowLeft, ArrowRight, ArrowUp, Check, CheckCheck, ChevronRight, Download, ImagePlus, Layers, LoaderCircle, Pencil, Plus, RotateCcw, Save, Sparkles, UploadCloud, X } from "@lucide/vue";
import { categoryFor, categories, dimensions, modulePurpose, moduleSection, needsAI, sourceAsset, referenceAssets, templates, usesSecondary, type Asset, type AssetRole, type DesignModule, type ProductCategory, type ProductInfo, type TemplateId } from "../../lib/design-model";
import { buildPhotographyPlan } from "../../lib/product-photography";
import type { StudioContext } from "../useStudio";
import CanvasPreview from "./CanvasPreview.vue";

const props = defineProps<{ studio: StudioContext }>();
const s = props.studio;
const p = computed(() => s.project.value);
const busy = computed(() => !!s.busy.value);
const step = computed({ get: () => s.step.value, set: value => { if (!busy.value) s.step.value = value; } });
const originalAssets = computed(() => p.value?.assets.filter(a => !a.generated) || []);
const profile = computed(() => categoryFor(p.value || {}));
const activeStyle = computed(() => templates.find(t => t.id === p.value?.template));
const activeModule = computed(() => p.value?.modules.find(m => m.id === s.editingId.value));
const activeReferences = computed(() => p.value && activeModule.value ? referenceAssets(p.value, activeModule.value) : []);
const activePhotography = computed(() => p.value && activeModule.value ? buildPhotographyPlan(p.value, activeModule.value, activeReferences.value) : null);
const compositions = [
  { value: "auto", label: "自动分镜", hint: "按整体场景、特写、卖点与参数安排不同画面" },
  { value: "immersive", label: "沉浸大图", hint: "商品铺满画面，标题直接叠在照片留白处" },
  { value: "split", label: "双图对照", hint: "并排展示两张实拍，文字不使用底色" },
  { value: "minimal", label: "简洁大图", hint: "保留一张商品大图与简短重点，文字不使用底色" },
] as const;
const textPositions = [
  { value: "auto", label: "默认右上" },
  { value: "top-right", label: "右上" },
  { value: "top-left", label: "左上" },
  { value: "bottom-right", label: "右下" },
  { value: "bottom-left", label: "左下" },
] as const;
const textColors = [
  { value: "auto", label: "自动对比" },
  { value: "dark", label: "深色文字" },
  { value: "light", label: "白色文字" },
] as const;
const copyResult = computed(() => s.copyResult.value?.projectId === p.value?.id ? s.copyResult.value : null);
const completed = computed(() => p.value?.workflow === "complete" || (!p.value?.workflow && p.value?.status === "ready"));
const unfinished = computed(() => p.value?.generation === "ai" && p.value.modules.some(m => needsAI(p.value!, m) && m.aiStatus !== "succeeded"));
const missingFacts = computed(() => {
  const info = p.value?.info;
  if (!info) return [];
  return [!info.material && "面料成分", !info.size && "尺寸规格", !info.care && "洗护说明", profile.value.id === "quilt" ? !info.filling && "填充物" : !info.setContents && "套件组成"].filter(Boolean);
});
const roles: Record<ProductCategory, AssetRole[]> = {
  quilt: ["整体", "叠放", "填充", "细节", "工艺", "颜色", "其他"],
  "bedding-set": ["整体", "被套", "床单", "枕套", "细节", "工艺", "颜色", "其他"],
};
const stages = [
  { id: "materials", label: "商品资料", hint: "素材与真实信息" },
  { id: "template", label: "视觉风格", hint: "选择排版方向" },
  { id: "plan", label: "内容计划", hint: "文案、图片与顺序" },
  { id: "results", label: "首图与整套", hint: "确认后导出" },
] as const;
const input = ref<HTMLInputElement | null>(null);
const dragging = ref(false);
const editDialog = ref<HTMLDialogElement | null>(null);
const previewSource = ref<Asset | null>(null);
const sourceDialog = ref<HTMLDialogElement | null>(null);

function info(key: keyof ProductInfo, event: Event) {
  s.updateInfo(key, (event.target as HTMLInputElement | HTMLTextAreaElement).value);
}
function setRole(asset: Asset, event: Event) {
  if (!p.value || busy.value) return;
  const role = (event.target as HTMLSelectElement).value as AssetRole;
  s.patchProject({ ...p.value, assets: p.value.assets.map(a => a.id === asset.id ? { ...a, role } : a) });
}
function planEdit(module: DesignModule, key: keyof DesignModule, event: Event) {
  if (busy.value) return;
  s.updatePlan(module.id, { [key]: (event.target as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement).value });
}
function localEdit(key: keyof DesignModule, event: Event) {
  if (busy.value) return;
  const target = event.target as HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement;
  s.updateModule({ [key]: key === "cropX" || key === "cropY" || key === "imageZoom" ? Number(target.value) : target.value });
}
function selectStyle(id: TemplateId) {
  if (busy.value) return;
  s.selectTemplate(id);
  s.step.value = "template";
}
function chooseStage(id: typeof stages[number]["id"]) {
  if (busy.value || !p.value) return;
  if ((id === "plan" || id === "results") && !p.value.modules.length) return;
  step.value = id;
}
function stageDisabled(id: string) { return busy.value || ((id === "plan" || id === "results") && !p.value?.modules.length); }
function uploadFiles(files: FileList | null) {
  if (!files?.length || busy.value) return;
  void s.importFiles(Array.from(files));
}
function uploadChanged(event: Event) {
  const target = event.target as HTMLInputElement;
  uploadFiles(target.files);
  target.value = "";
}
function dropFiles(event: DragEvent) { dragging.value = false; uploadFiles(event.dataTransfer?.files || null); }
function isHero(m: DesignModule) { return moduleSection(m) === "hero" || m.index === 1; }
function factsOnly(m: DesignModule) { return moduleSection(m) === "specs" || (p.value?.template === "vip" && moduleSection(m) === "care"); }
function secondaryLabel(m: DesignModule) {
  const section = moduleSection(m);
  return section === "components" ? "另一组件实拍" : section === "colors" ? "另一配色实拍" : "整体对照实拍";
}
function canMove(i: number, delta: number) {
  if (!p.value || busy.value || p.value.template !== "vip") return false;
  const current = p.value.modules[i], next = p.value.modules[i + delta];
  return !!next && next.kind === current.kind && moduleSection(current) !== "hero" && moduleSection(next) !== "hero";
}
function sourceHint(m: DesignModule) {
  const asset = p.value && sourceAsset(p.value, m);
  if (moduleSection(m) === "filling" && asset?.role !== "填充" && asset?.role !== "叠放") return "当前使用已有实拍，可补充填充或叠放照片。";
  if (moduleSection(m) === "components") return "分别选择当前商品实际包含的被套、床单或枕套。";
  if (isHero(m) && profile.value.id === "quilt" && asset?.role !== "叠放") return "叠放照片更容易展现被子的体积与蓬松感。";
  return "";
}
function imageStatus(m: DesignModule) {
  if (m.aiStatus === "succeeded" && p.value?.assets.find(a => a.id === m.imageId)?.generated) return "AI摄影 · 已排版";
  if (p.value?.generation !== "ai" || !p.value || !needsAI(p.value, m)) return "实拍排版";
  if (m.aiStatus === "succeeded") return "实拍排版";
  return m.aiStatus === "failed" ? "生成失败" : "等待生成";
}
function editImage(m: DesignModule) { if (!busy.value) s.editingId.value = m.id; }
function closeEdit() { if (!busy.value) s.editingId.value = null; }
function goHome() { if (!busy.value) s.view.value = "home"; }
function retry(m?: DesignModule) { if (p.value) void s.runAI(p.value, m?.id); }
watch(activeModule, async (value) => {
  await nextTick();
  if (value && !editDialog.value?.open) editDialog.value?.showModal();
  if (!value && editDialog.value?.open) editDialog.value?.close();
}, { immediate: true });
watch(previewSource, async (value) => {
  await nextTick();
  if (value && !sourceDialog.value?.open) sourceDialog.value?.showModal();
  if (!value && sourceDialog.value?.open) sourceDialog.value?.close();
});
onBeforeUnmount(() => { editDialog.value?.close(); sourceDialog.value?.close(); });
</script>

<template>
  <section v-if="p" class="product-editor">
    <header class="editor-heading">
      <div class="heading-copy">
        <button class="back-link" @click="goHome"><ArrowLeft :size="15" />返回工作台</button>
        <div class="title-row"><h1>{{ p.info.name || "新商品" }}</h1><span class="save-indicator" :class="{ dirty: s.dirty.value }"><i />{{ s.dirty.value ? '有未保存修改' : p.sample ? '样例体验' : '已保存' }}</span></div>
        <p>{{ profile.name }} · {{ p.output === 'detail' ? '7 张详情切片 / 790 px' : p.output === 'main' ? '5 张主图 / 1200 × 1200 px' : '主图与详情套图' }}</p>
      </div>
      <div class="heading-actions"><button class="button" :disabled="busy" @click="s.save()"><Save :size="17" />保存作品</button><button class="button primary" :disabled="busy || !completed || unfinished" @click="s.downloadAll()"><Download :size="17" />整套导出</button></div>
    </header>

    <nav class="stepper" aria-label="制作步骤">
      <button v-for="(stage, i) in stages" :key="stage.id" :class="{ active: step === stage.id, passed: stages.findIndex(x => x.id === step) > i }" :disabled="stageDisabled(stage.id)" :aria-current="step === stage.id ? 'step' : undefined" @click="chooseStage(stage.id)"><span class="step-number"><Check v-if="stages.findIndex(x => x.id === step) > i" :size="16" /><template v-else>{{ String(i + 1).padStart(2, '0') }}</template></span><span><b>{{ stage.label }}</b><small>{{ stage.hint }}</small></span><ChevronRight v-if="i !== stages.length - 1" :size="17" class="step-arrow" /></button>
    </nav>

    <div v-if="busy" class="task-banner" role="status"><LoaderCircle :size="19" class="spin" /><div><b>{{ s.busy.value }}</b><progress v-if="s.progress.value > 0" :value="s.progress.value" max="100" /><small>处理完成后可继续编辑</small></div><span v-if="s.progress.value > 0">{{ s.progress.value }}%</span></div>

    <template v-if="step === 'materials'">
      <div class="materials-layout">
        <section class="panel photos-panel">
          <div class="panel-heading"><div><span class="section-kicker">01 / 商品素材</span><h2>让实拍成为主角 <span>{{ originalAssets.length }}/40</span></h2></div><button class="button subtle small" :disabled="busy" @click="input?.click()"><Plus :size="16" />添加素材</button></div>
          <input ref="input" type="file" multiple accept=".jpg,.jpeg,.png,.webp,.zip" class="visually-hidden" @change="uploadChanged" />
          <button class="upload-area" :class="{ dragging }" :disabled="busy" @click="input?.click()" @dragover.prevent="dragging = true" @dragleave="dragging = false" @drop.prevent="dropFiles"><span class="upload-icon"><UploadCloud :size="28" /></span><b>拖入商品照片，或点击上传</b><span>JPG、PNG、WebP、ZIP · 1 张实拍即可开始</span></button>
          <div v-if="originalAssets.length" class="photo-grid">
            <article v-for="asset in originalAssets" :key="asset.id" class="photo-card"><button class="photo-image" :aria-label="`查看素材 ${asset.name}`" @click="previewSource = asset"><img :src="appPath(asset.url)" :alt="asset.name" /><span>预览素材</span></button><button class="remove-photo" :disabled="busy" :aria-label="`移除素材 ${asset.name}`" @click="s.removeProjectAsset(asset)"><X :size="13" /></button><div class="photo-details"><span :title="asset.name">{{ asset.name }}</span><select :value="asset.role" :disabled="busy" :aria-label="`${asset.name}的用途`" @change="setRole(asset, $event)"><option v-for="role in Array.from(new Set([asset.role, ...roles[profile.id]]))" :key="role" :value="role">{{ role }}图</option></select></div></article>
          </div>
          <div class="photo-guide"><ImagePlus :size="18" /><div><b>多一个角度，商品就多一分说服力</b><p>{{ profile.photoGuide }}</p><small>标记照片用途，系统会优先匹配对应内容；素材较少时会复用实拍。</small></div></div>
        </section>
        <section class="panel facts-panel">
          <div class="panel-heading"><div><span class="section-kicker">02 / 商品资料</span><h2>填真实信息，写有据可依的文案</h2></div></div>
          <fieldset :disabled="busy">
            <label class="field">商品类目<div class="category-switch"><button v-for="category in categories" :key="category.id" type="button" :class="{ chosen: profile.id === category.id }" :aria-pressed="profile.id === category.id" @click="s.changeCategory(category.id)">{{ category.name }}<Check v-if="profile.id === category.id" :size="14" /></button></div></label>
            <label class="field">商品名称 <em>*</em><input :value="p.info.name" maxlength="40" :placeholder="profile.id === 'quilt' ? '例如：华夫格大豆被' : '例如：小花印花四件套'" @input="info('name', $event)" /></label>
            <div class="field-pair"><label class="field">品牌名称<input :value="p.info.brand" maxlength="30" @input="info('brand', $event)" /></label><label class="field">一句话定位<input :value="p.info.subtitle" maxlength="70" placeholder="例如：格纹肌理，柔软蓬松" @input="info('subtitle', $event)" /></label></div>
            <label class="field">已确认的卖点<textarea :value="p.info.sellingPoints" maxlength="300" rows="3" placeholder="每行一个，按重要程度排列；例如已确认的面料、工艺特点" @input="info('sellingPoints', $event)" /><small>建议 3–6 个卖点，AI 会根据这些资料编写其余图片文案。</small></label>
            <div class="field-pair"><label class="field">面料成分<input :value="p.info.material" maxlength="60" placeholder="按实际标签填写" @input="info('material', $event)" /></label><label v-if="profile.id === 'quilt'" class="field">填充物<input :value="p.info.filling" maxlength="60" placeholder="未确认可留空" @input="info('filling', $event)" /></label><label v-else class="field">套件组成<input :value="p.info.setContents || ''" maxlength="160" placeholder="被套 ×1、床单 ×1、枕套 ×2" @input="info('setContents', $event)" /></label><label class="field">尺寸规格<input :value="p.info.size" maxlength="80" :placeholder="profile.id === 'quilt' ? '实际长 × 宽' : '分别填写各组件尺寸'" @input="info('size', $event)" /></label><label v-if="profile.id === 'quilt'" class="field">重量<input :value="p.info.weight" maxlength="60" placeholder="未确认可留空" @input="info('weight', $event)" /></label></div>
            <label class="field">{{ profile.id === 'quilt' ? '颜色名称' : '花型 / 配色名称' }}<input :value="p.info.colors" maxlength="60" placeholder="按店铺实际名称填写" @input="info('colors', $event)" /></label><label class="field">洗护说明<textarea :value="p.info.care" maxlength="160" rows="2" placeholder="按商品洗护标识填写" @input="info('care', $event)" /></label>
          </fieldset><p class="field-footnote">未填写的参数会从成品中省略。</p>
        </section>
      </div>
      <footer class="step-footer"><span><Layers :size="17" />当前风格：{{ activeStyle?.name }}</span><div><button class="button" :disabled="busy" @click="step = 'template'">选择视觉风格</button><button class="button primary" :disabled="busy" @click="s.preparePlan()">制定内容计划<ArrowRight :size="17" /></button></div></footer>
    </template>

    <template v-else-if="step === 'template'">
      <section class="style-intro"><div><span class="section-kicker">为商品选择呈现方式</span><h2>视觉统一，卖点清楚</h2><p>{{ profile.summary }}</p></div><a :href="profile.referenceUrl" target="_blank" rel="noreferrer">查看{{ profile.name }}风格参考 ↗</a></section>
      <div class="style-grid"><button v-for="style in templates" :key="style.id" class="style-card" :class="{ chosen: p.template === style.id }" :aria-pressed="p.template === style.id" :disabled="busy" @click="selectStyle(style.id)"><div class="style-art" :style="{ background: style.bg, color: style.ink }"><img :src="appPath(style.image)" :alt="`${style.name}排版示意`" /><strong>{{ style.id === 'vip' ? '看得见的蓬松与质感' : style.id === 'clean' ? '让好物，自在呈现' : style.id === 'warm' ? '把温柔，铺进日常' : '在细节里，发现质感' }}</strong><small>排版示意 · 使用你的商品素材制作</small></div><div class="style-meta"><div><h3>{{ style.name }}</h3><p>{{ style.description }}</p></div><span class="style-check"><Check v-if="p.template === style.id" :size="17" /><Plus v-else :size="17" /></span></div></button></div>
      <footer class="step-footer"><span>切换风格时，会保留对应模块中已编辑的文案。</span><div><button class="button" :disabled="busy" @click="step = 'materials'"><ArrowLeft :size="16" />商品资料</button><button class="button primary" :disabled="busy" @click="s.preparePlan()">下一步：内容计划<ArrowRight :size="17" /></button></div></footer>
    </template>

    <template v-else-if="step === 'plan'">
      <section class="plan-intro"><div><span class="section-kicker">内容先行 / {{ p.modules.length }} 张图</span><h2>每张图，只讲一个重点</h2><p>首图文案由你填写，其余图片可以交给 AI。确定卖点与选图后，再预览效果。</p></div><button class="button primary" :disabled="busy || !p.modules.some(m => !isHero(m))" @click="s.generateCopy()"><LoaderCircle v-if="s.copyBusy.value" :size="17" class="spin" /><Sparkles v-else :size="17" />{{ s.copyBusy.value ? '正在编写' : 'AI 生成其他图文案' }}</button></section>
      <div v-if="copyResult" class="message-bar" :class="{ error: copyResult.error }" :role="copyResult.error ? 'alert' : 'status'"><span>{{ copyResult.message }}</span><button v-if="copyResult.before" class="text-button" :disabled="busy" @click="s.undoCopy()"><RotateCcw :size="14" />撤销本次生成</button></div>
      <p v-if="missingFacts.length" class="fact-reminder">待补充：{{ missingFacts.join('、') }}。可返回商品资料填写，AI 不会自动编造这些参数。</p>
      <div class="plan-list"><article v-for="(m, i) in p.modules" :key="m.id" class="plan-card" :class="{ 'hero-plan': isHero(m) }"><div class="plan-label"><span class="plan-number">{{ String(i + 1).padStart(2, '0') }}</span><b>{{ modulePurpose(m).split(' · ')[0] }}</b><small>{{ m.kind === 'main' ? '商品主图' : '详情模块' }}</small><div v-if="p.template === 'vip' && moduleSection(m) !== 'hero'" class="move-actions"><button class="icon-button" :disabled="!canMove(i, -1)" :aria-label="`上移${modulePurpose(m)}`" @click="s.moveModule(m.id, -1)"><ArrowUp :size="15" /></button><button class="icon-button" :disabled="!canMove(i, 1)" :aria-label="`下移${modulePurpose(m)}`" @click="s.moveModule(m.id, 1)"><ArrowDown :size="15" /></button></div></div><fieldset class="plan-copy" :disabled="busy"><span class="copy-chip" :class="{ manual: isHero(m) }">{{ isHero(m) ? '首图文案 · 由你填写' : 'AI 文案 · 可手动修改' }}</span><label class="field">{{ isHero(m) ? '首图主标题' : '主标题' }}<textarea :value="m.title" maxlength="40" rows="2" placeholder="建议 1–2 行，回车可手动换行" @input="planEdit(m, 'title', $event)" /><small>建议 1–2 行短标题，回车可手动换行。</small></label><label class="field">补充说明<textarea :value="m.subtitle" maxlength="100" rows="2" placeholder="一句话说明，让照片证明卖点" @input="planEdit(m, 'subtitle', $event)" /></label></fieldset><div class="plan-photo"><template v-if="factsOnly(m)"><div class="facts-source"><Layers :size="23" /><b>{{ moduleSection(m) === 'specs' ? '使用商品真实参数' : '选购与洗护信息' }}</b><span>{{ moduleSection(m) === 'specs' ? '根据已填写的商品资料排版' : p.info.care || '在商品资料中填写洗护标识内容' }}</span></div></template><template v-else><img v-if="sourceAsset(p, m)" :src="appPath(sourceAsset(p, m)?.url || '')" :alt="`${modulePurpose(m)}选用的实拍`" /><label class="field">对应实拍<select :value="sourceAsset(p, m)?.id || ''" :disabled="busy" :aria-label="`${modulePurpose(m)}的原始实拍`" @change="planEdit(m, 'imageId', $event)"><option value="" disabled>选择原始实拍</option><option v-for="asset in originalAssets" :key="asset.id" :value="asset.id">{{ asset.role }} · {{ asset.name }}</option></select></label><label v-if="usesSecondary(m)" class="field">{{ secondaryLabel(m) }}<select :value="m.sourceImageId2 || m.imageId2" :disabled="busy" :aria-label="`${modulePurpose(m)}的第二张实拍`" @change="planEdit(m, 'imageId2', $event)"><option value="">暂不使用</option><option v-for="asset in originalAssets" :key="asset.id" :value="asset.id">{{ asset.role }} · {{ asset.name }}</option></select></label><small v-if="sourceHint(m)" class="source-hint">{{ sourceHint(m) }}</small></template></div><details v-if="needsAI(p, m)" class="plan-shot"><summary><Sparkles :size="14" />这一张的摄影分镜</summary><p>{{ buildPhotographyPlan(p, m, referenceAssets(p, m)).shot }}</p></details></article></div>
      <footer class="plan-next"><div><span class="section-kicker">{{ completed ? '整套图片已就绪' : '先看首图，再完成整套' }}</span><h3>{{ completed ? '修改文案后，检查整套效果' : '让这一张，确定整套的方向' }}</h3><p>{{ completed ? '已生成图片继续使用，文案修改同步到排版。' : '实拍直接排版；AI 按不同分镜安排首图、场景和卖点画面，纹理、工艺与配色保留真实实拍。' }}</p></div><div class="plan-next-actions"><button v-if="completed" class="button primary" :disabled="busy" @click="step = 'results'">查看更新后的整套图<ArrowRight :size="17" /></button><template v-else><button class="button" :disabled="busy" @click="s.previewPlan('template')">实拍预览首图</button><button class="button primary" :disabled="busy" @click="s.previewPlan('ai')"><Sparkles :size="17" />AI 优化首图</button></template></div></footer>
      <div class="replan"><span>资料有更新？重新安排其余文案和选图，首图保留手动文案。</span><button class="text-button" :disabled="busy" @click="s.preparePlan(true)"><RotateCcw :size="14" />按最新资料重新规划</button></div>
    </template>

    <template v-else-if="step === 'results'">
      <section v-if="!p.modules.length || p.workflow === 'plan'" class="empty-results panel"><Layers :size="36" /><h2>先完成内容计划</h2><p>确定每张图的卖点与对应实拍，再查看首图排版。</p><button class="button primary" :disabled="busy" @click="step = p.modules.length ? 'plan' : 'materials'">{{ p.modules.length ? '返回内容计划' : '添加商品素材' }}<ArrowRight :size="16" /></button></section>
      <section v-else-if="p.workflow === 'preview' && p.modules[0]" class="first-preview"><button class="first-art" :disabled="busy" aria-label="编辑首图" @click="editImage(p.modules[0])"><CanvasPreview :project="p" :module="p.modules[0]" large /><span class="edit-hint"><Pencil :size="15" />点击调整文案与裁切</span></button><div class="first-checklist"><span class="section-kicker">首图确认 / {{ p.generation === 'ai' ? 'AI 优化' : '实拍排版' }}</span><h2>这一张，决定整套的感觉</h2><p>确认标题、商品占比与色调，满意后再完成整套图片。</p><ul><li><Check :size="17" />主标题抓住商品的核心卖点</li><li><Check :size="17" />商品足够突出，文字排版清楚</li><li><Check :size="17" />花型与纹理和真实商品一致</li></ul><div v-if="p.generation === 'ai' && p.modules[0].aiStatus !== 'succeeded'" class="message-bar error"><span>{{ p.modules[0].aiError || '首图尚未生成完成' }}</span><button class="text-button" :disabled="busy" @click="retry(p.modules[0])">重试首图</button></div><button class="button primary full" :disabled="busy || (p.generation === 'ai' && needsAI(p, p.modules[0]) && p.modules[0].aiStatus !== 'succeeded')" @click="s.completePlan()"><CheckCheck :size="17" />确认首图，完成整套</button><button class="button full" :disabled="busy" @click="step = 'plan'">返回调整文案与选图</button><small>{{ p.generation === 'ai' ? `确认后还将优化 ${p.modules.slice(1).filter(m => needsAI(p!, m)).length} 张商品摄影，使用当前自定义 API。` : '实拍排版不调用模型，确认后展示整套。' }}</small></div></section>
      <template v-else><div class="results-heading"><div><span class="section-kicker">{{ unfinished ? '继续完成剩余图片' : '排版已完成' }}</span><h2>{{ (p.output || s.outputTab.value) === 'detail' ? '商品详情，一屏一个重点' : '商品主图，按顺序讲清卖点' }}</h2><p>点击图片可改字、换图或调整裁切，导出前请检查商品外观与参数。</p></div><button class="button" :disabled="busy" @click="step = 'plan'"><Pencil :size="16" />调整卖点与顺序</button></div><div v-if="unfinished" class="message-bar error"><span>已完成图片会保留，其余图片可以继续生成。</span><button class="button small" :disabled="busy" @click="retry()"><Sparkles :size="15" />继续未完成图片</button></div><div v-if="!p.output" class="result-switch"><button :class="{ chosen: s.outputTab.value === 'main' }" @click="s.outputTab.value = 'main'">商品主图 · 5</button><button :class="{ chosen: s.outputTab.value === 'detail' }" @click="s.outputTab.value = 'detail'">详情切片 · 7</button></div><div class="result-size"><span>{{ (p.output || s.outputTab.value) === 'main' ? '1200 × 1200 px' : '790 px 宽 · 完整详情切片' }}</span><span>JPG · 按序导出</span></div><div class="results-grid" :class="{ detail: (p.output || s.outputTab.value) === 'detail' }"><article v-for="m in p.modules.filter(m => m.kind === (p!.output || s.outputTab.value))" :key="m.id" class="result-card"><button class="result-art" :disabled="busy" :aria-label="`编辑${m.kind === 'main' ? '主图' : '详情'}${m.index}`" @click="editImage(m)"><CanvasPreview :project="p" :module="m" /><span class="edit-hint"><Pencil :size="14" />编辑这一张</span></button><div class="result-meta"><div><b>{{ m.kind === 'main' ? '主图' : '详情' }} {{ String(m.index).padStart(2, '0') }}</b><span :class="{ failed: m.aiStatus === 'failed' }">{{ imageStatus(m) }}<template v-if="m.kind === 'detail'"> · 790 × {{ dimensions(m).height }}</template></span></div><button class="icon-button" :disabled="busy" :aria-label="`下载${m.kind === 'main' ? '主图' : '详情'}${m.index}`" @click="s.downloadOne(m)"><Download :size="18" /></button></div></article></div><footer class="step-footer"><span><Check :size="17" />导出前核对商品花色、细节、文案与真实参数。</span><button class="button primary" :disabled="busy || unfinished" @click="s.downloadAll()"><Download :size="17" />导出整套图片</button></footer></template>
    </template>

    <Teleport to="body">
      <dialog ref="editDialog" class="product-edit-dialog" aria-labelledby="edit-title" @cancel.prevent="closeEdit" @click="($event.target === $event.currentTarget) && closeEdit()">
        <div v-if="activeModule" class="dialog-shell">
          <header class="dialog-heading"><div><span>局部编辑 / 实时预览</span><h2 id="edit-title">{{ activeModule.kind === 'main' ? '主图' : '详情' }} {{ String(activeModule.index).padStart(2, '0') }}</h2></div><button class="icon-button" :disabled="busy" aria-label="关闭编辑" @click="closeEdit"><X :size="21" /></button></header>
